require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/_layout.php'; $u=require_admin(); $ok=$err=''; $preview=[]; $previewType='';
function csv_rows(string $tmp): array {$h=fopen($tmp,'r');if(!$h)throw new RuntimeException('Could not read CSV.');$head=fgetcsv($h);if(!$head)throw new RuntimeException('CSV has no header.');$head=array_map(fn($x)=>strtolower(trim((string)$x)),$head);$out=[];while(($r=fgetcsv($h))!==false){if(count($r)!==count($head))continue;$out[]=array_combine($head,$r);}fclose($h);return $out;}
function save_preview(array $rows,string $type): string {$token=bin2hex(random_bytes(16));$_SESSION['migration_preview_'.$token]=['rows'=>$rows,'type'=>$type,'at'=>time()];return $token;}
function get_preview(string $token): array {$x=$_SESSION['migration_preview_'.$token]??null;if(!$x||time()-($x['at']??0)>1800)throw new RuntimeException('Migration preview expired. Upload the CSV again.');return $x;}
function paymenter_customer_normalize(array $r): array {$id=(int)($r['paymenter_user_id']??$r['id']??0);$first=trim($r['first_name']??'');$last=trim($r['last_name']??'');$name=trim($r['name']??trim($first.' '.$last));$email=strtolower(trim($r['email']??''));return compact('id','name','email');}
function paymenter_service_normalize(array $r): array {return ['id'=>(int)($r['paymenter_service_id']??0),'email'=>strtolower(trim($r['email']??'')),'name'=>trim($r['server_name']??$r['service_name']??$r['product_name']??'Imported server'),'product'=>trim($r['product_name']??''),'status'=>strtolower(trim($r['status']??'active')),'price'=>(float)($r['price']??$r['price_monthly']??0),'currency'=>strtoupper(trim($r['currency_code']??'EUR')),'expires'=>trim($r['expires_at']??$r['next_due_at']??''),'pid'=>(int)($r['pterodactyl_server_id']??$r['ptero_server_id']??0),'ident'=>trim($r['pterodactyl_identifier']??$r['ptero_identifier']??''),'puid'=>(int)($r['pterodactyl_user_id']??0)];}
function verify_ptero_import(array $s): array {if(!$s['pid'])return ['bad','Missing server ID'];try{$j=app_ptero('/servers/'.$s['pid']);$a=$j['attributes']??[];$actual=(string)($a['identifier']??'');if($s['ident']!==''&&$actual!==''&&!hash_equals($actual,$s['ident']))return ['bad','Identifier mismatch (API: '.$actual.')'];return ['ok','Found: '.($a['name']??('server #'.$s['pid'])).($actual?' · '.$actual:'')];}catch(Throwable $e){return ['bad',$e->getMessage()];}}
