 $catMap=[];$created=0;$updated=0;
 foreach($cats as $c){$q=db()->prepare('SELECT id FROM store_categories WHERE paymenter_category_id=? OR slug=? LIMIT 1');$q->execute([$c[0],$c[1]]);$id=(int)$q->fetchColumn();if($id){db()->prepare("UPDATE store_categories SET paymenter_category_id=?,source='paymenter' WHERE id=?")->execute([$c[0],$id]);$updated++;}else{$q=db()->prepare("INSERT INTO store_categories(name,slug,description,sort_order,paymenter_category_id,source) VALUES(?,?,?,?,?,'paymenter')");$q->execute([$c[2],$c[1],$c[3],$c[0]*10,$c[0]]);$id=(int)db()->lastInsertId();$created++;}$catMap[$c[0]]=$id;}
 foreach($products as $p){$q=db()->prepare('SELECT id FROM store_products WHERE paymenter_product_id=? OR slug=? LIMIT 1');$q->execute([$p[0],$p[3]]);$id=(int)$q->fetchColumn();$cid=$catMap[$p[1]];if($id){db()->prepare("UPDATE store_products SET paymenter_product_id=?,source='paymenter' WHERE id=?")->execute([$p[0],$id]);$updated++;}else{$q=db()->prepare("INSERT INTO store_products(category_id,name,slug,description,price_monthly,ram_mb,disk_mb,cpu_percent,backups,database_limit,allocation_limit,active,sort_order,paymenter_product_id,billing_period,billing_unit,source) VALUES(?,?,?,?,?,?,?,?,1,1,1,1,?,?,1,'month','paymenter')");$q->execute([$cid,$p[2],$p[3],$p[4],$p[5],$p[6],$p[7],$p[8],$p[0]*10,$p[0]]);$id=(int)db()->lastInsertId();$created++;}
  db()->prepare("UPDATE services s JOIN migration_links ml ON ml.local_id=s.id AND ml.source='paymenter' AND ml.entity_type='service' SET s.product_id=?,s.mapped_product_id=? WHERE JSON_UNQUOTE(JSON_EXTRACT(s.config_json,'$.product_name'))=?")->execute([$id,$id,$p[2]]);
 }
 return [$created,$updated];
