if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'preview';
 if($action==='import_paymenter_store'){[$c,$up]=import_paymenter_store_snapshot();$ok="Paymenter store imported: $c created, $up linked/updated. Configure Egg / Location / Node for imported products before selling them.";audit_log('migration.paymenter_store','store',null,$ok);}
 elseif($action==='preview'){if(empty($_FILES['csv']['tmp_name']))throw new RuntimeException('Choose a CSV file.');$type=$_POST['type']??'';$rows=csv_rows($_FILES['csv']['tmp_name']);if(!in_array($type,['paymenter_customers','paymenter_services'],true))throw new RuntimeException('Invalid import type.');$previewType=$type;foreach($rows as $r){if($type==='paymenter_customers'){$n=paymenter_customer_normalize($r);$q=db()->prepare('SELECT id FROM users WHERE email=?');$q->execute([$n['email']]);$existing=(int)$q->fetchColumn();$preview[]=['raw'=>$r,'n'=>$n,'state'=>(!$n['id']||!filter_var($n['email'],FILTER_VALIDATE_EMAIL)||!$n['name'])?'bad':($existing?'skip':'ok'),'message'=>$existing?'Existing customer #'.$existing:'Ready to import'];}else{$n=paymenter_service_normalize($r);$q=db()->prepare('SELECT id FROM users WHERE email=?');$q->execute([$n['email']]);$uid=(int)$q->fetchColumn();$q=db()->prepare("SELECT s.id FROM services s LEFT JOIN migration_links ml ON ml.entity_type='service' AND ml.local_id=s.id AND ml.source='paymenter' WHERE s.ptero_server_id=? OR (ml.source_id=? AND ml.entity_type='service') LIMIT 1");$q->execute([$n['pid'],$n['id']]);$existing=(int)$q->fetchColumn();$v=verify_ptero_import($n);$state=(!$uid||!$n['id']||!$n['pid']||$v[0]==='bad')?'bad':($existing?'skip':'ok');$msg=!$uid?'Customer must be imported first':($existing?'Already linked to service #'.$existing:$v[1]);$preview[]=['raw'=>$r,'n'=>$n,'state'=>$state,'message'=>$msg];}}$token=save_preview(array_column($preview,'raw'),$type);
 }elseif($action==='import'){$token=(string)($_POST['token']??'');$x=get_preview($token);$type=$x['type'];$rows=$x['rows'];$created=$skip=$failed=0;foreach($rows as $r){try{if($type==='paymenter_customers'){$n=paymenter_customer_normalize($r);if(!$n['id']||!filter_var($n['email'],FILTER_VALIDATE_EMAIL)||!$n['name'])throw new RuntimeException('Invalid customer row');$q=db()->prepare('SELECT id,ptero_user_id FROM users WHERE email=?');$q->execute([$n['email']]);$existing=$q->fetch();$local=(int)($existing['id']??0);if(!$local){$pw=password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT);$q=db()->prepare("INSERT INTO users(name,email,password_hash,role,account_status) VALUES(?,?,?,'customer','active')");$q->execute([$n['name'],$n['email'],$pw]);$local=(int)db()->lastInsertId();$existing=['ptero_user_id'=>null];$created++;}else $skip++;try{$pteroUserId=ensure_ptero_user_for_local_user($n['email'],$n['name'],true);if($pteroUserId && empty($existing['ptero_user_id']))db()->prepare('UPDATE users SET ptero_user_id=? WHERE id=?')->execute([$pteroUserId,$local]);}catch(Throwable $e){}db()->prepare("INSERT INTO migration_links(source,entity_type,source_id,local_id,metadata) VALUES('paymenter','user',?,?,?) ON DUPLICATE KEY UPDATE local_id=VALUES(local_id),metadata=VALUES(metadata)")->execute([$n['id'],$local,json_encode(['email'=>$n['email']])]);}else{$n=paymenter_service_normalize($r);$q=db()->prepare('SELECT id,ptero_user_id FROM users WHERE email=?');$q->execute([$n['email']]);$cu=$q->fetch();if(!$cu)throw new RuntimeException('Customer not found: '.$n['email']);$v=verify_ptero_import($n);if($v[0]!=='ok')throw new RuntimeException($v[1]);$q=db()->prepare("SELECT s.id FROM services s LEFT JOIN migration_links ml ON ml.entity_type='service' AND ml.local_id=s.id AND ml.source='paymenter' WHERE s.ptero_server_id=? OR (ml.source_id=? AND ml.entity_type='service') LIMIT 1");$q->execute([$n['pid'],$n['id']]);$local=(int)$q->fetchColumn();if($local){$skip++;}else{$due=null;if($n['expires']&&substr($n['expires'],0,4)!=='9999')$due=date('Y-m-d H:i:s',strtotime($n['expires']));$status=in_array($n['status'],['active','suspended','cancelled'],true)?$n['status']:'active';$q=db()->prepare("INSERT INTO services(user_id,name,status,price_monthly,currency,next_due_at,ptero_server_id,ptero_identifier,auto_renew,config_json) VALUES(?,?,?,?,?,?,?,?,0,?)");$q->execute([(int)$cu['id'],$n['name'],$status,$n['price'],$n['currency']?:'EUR',$due,$n['pid'],$n['ident']?:null,json_encode(['imported'=>true,'source'=>'Paymenter','paymenter_service_id'=>$n['id'],'product_name'=>$n['product'],'billing_mode'=>'manual'])]);$local=(int)db()->lastInsertId();$created++;}if(!$cu['ptero_user_id']&&$n['puid'])db()->prepare('UPDATE users SET ptero_user_id=? WHERE id=?')->execute([$n['puid'],$cu['id']]);db()->prepare("INSERT INTO migration_links(source,entity_type,source_id,local_id,metadata) VALUES('paymenter','service',?,?,?) ON DUPLICATE KEY UPDATE local_id=VALUES(local_id),metadata=VALUES(metadata)")->execute([$n['id'],$local,json_encode(['ptero_server_id'=>$n['pid'],'identifier'=>$n['ident']])]);}}catch(Throwable $e){$failed++;}}
  // Derive failures from the final row totals so a successful row can never also be counted as failed.
  $failed=max(0,count($rows)-$created-$skip);
  $q=db()->prepare('INSERT INTO migration_imports(admin_user_id,import_type,filename,rows_total,rows_created,rows_skipped,rows_failed,summary) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$u['id'],$type,'Paymenter preview import',count($rows),$created,$skip,$failed,'Direct Paymenter migration with Pterodactyl verification']);audit_log('migration.paymenter',$type,null,"created=$created skipped=$skip failed=$failed");unset($_SESSION['migration_preview_'.$token]);$ok="Import finished: $created created, $skip skipped, $failed failed.";
 }}catch(Throwable $e){$err=$e->getMessage();}}
$history=db()->query('SELECT m.*,u.name admin_name FROM migration_imports m LEFT JOIN users u ON u.id=m.admin_user_id ORDER BY m.id DESC LIMIT 30')->fetchAll();admin_head($u,'Paymenter Migration','migration');?>
